import java.util.*;
import java.util.stream.*;

public class Sales {
  record Order(String region, int amount) {}

  public static void main(String[] args) {
    var orders = List.of(
      new Order("EU", 100),
      new Order("US", 200),
      new Order("EU", 50),
      new Order("US", 75)
    );

    Map<String, Integer> totals = orders.stream()
      .collect(Collectors.groupingBy(
        Order::region,
        TreeMap::new,
        Collectors.summingInt(Order::amount)));

    totals.forEach((region, total) -> System.out.println(region + "=" + total));
  }
}

